import boto3


def get_translate_client(config=None):
    config = config or {}
    return boto3.client('translate', region_name=config.get('region'))

from typing import Dict


class TranslationRequest:
    def __init__(self, text: str, source_language: str, target_language: str):
        self.text = text
        self.source_language = source_language
        self.target_language = target_language

    def to_dict(self) -> Dict:
        return {
            'Text': self.text,
            'SourceLanguageCode': self.source_language,
            'TargetLanguageCode': self.target_language,
        }


class TranslationResponse:
    def __init__(self, text: str, source_language: str, target_language: str):
        self.text = text
        self.source_language = source_language
        self.target_language = target_language

    @classmethod
    def from_dict(cls, data: Dict):
        return cls(
            text=data['TranslatedText'],
            source_language=data['SourceLanguageCode'],
            target_language=data['TargetLanguageCode'],
        )

    def to_dict(self) -> Dict:
        return {
            'text': self.text,
            'source_language': self.source_language,
            'target_language': self.target_language,
        }

import boto3

from translation_client import get_translate_client
from translation_models import TranslationResponse


def quality_summary(texts, source_language, target_language, config=None):
    client = get_translate_client(config)
    responses = client.batch_translate_text(
        Requests=[
            {
                'Text': text,
                'SourceLanguageCode': source_language,
                'TargetLanguageCode': target_language,
            }
            for text in texts
        ]
    )
    summary = {
        'source_language': source_language,
        'target_language': target_language,
        'translations': [
            TranslationResponse.from_dict(response).to_dict()
            for response in responses['TranslatedTexts']
        ],
    }
    return summary

